Method.Source:
/// <summary>
/// DebuC 23.08.21 Req 3654 Task 4545
///     Edit NDXIsSalesItem and NDXIsCatalogItem by changing NDXItemUsageId
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(InventTable), DataEventType::ModifiedField)]
public static void InventTable_onModifiedField(Common sender, DataEventArgs e)
{
    ModifyFieldEventArgs	eventArgs	= e;
    InventTable				inventTable = sender;
    FieldId					fieldId		= eventArgs.parmFieldId();

    switch(fieldId)
    {
        case fieldNum(InventTable, KCS_ItemUsageId):
            inventTable.KCS_IsSalesItem		= KCS_ItemUsageIds::find(inventTable.KCS_ItemUsageId).KCS_IsSalesItem;
            inventTable.KCS_IsCatalogItem	= KCS_ItemUsageIds::find(inventTable.KCS_ItemUsageId).IsCatalogItem;
            break;

        case fieldNum(InventTable, NDX_PhysicalDimensionsChecked):
            if(inventTable.NDX_PhysicalDimensionsChecked)
            {
                inventTable.NDX_PhysicalDimensionCheckedDateTime    = DateTimeUtil::utcNow();
                inventTable.NDX_PhysicalDimensionCheckedBy          = curUserId();
            }
            else
            {
                inventTable.NDX_PhysicalDimensionCheckedDateTime    = DateTimeUtil::minValue();
                inventTable.NDX_PhysicalDimensionCheckedBy          = '';
            }
            break;

        case fieldNum(InventTable, NDX_NominalDimensionsChecked):
            if(inventTable.NDX_NominalDimensionsChecked)
            {
                inventTable.NDX_NominalDimensionCheckedDateTime    = DateTimeUtil::utcNow();
                inventTable.NDX_NominalDimensionCheckedBy          = curUserId();
            }
            else
            {
                inventTable.NDX_NominalDimensionCheckedDateTime    = DateTimeUtil::minValue();
                inventTable.NDX_NominalDimensionCheckedBy          = '';
            }
            break;

    }
}

