/// <summary>
/// PaffH 15.04.25
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(InventTable), DataEventType::Updating)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void InventTable_onUpdating(Common sender, DataEventArgs e)
{
    // save changeLog POP specific Datamanagement
    InventTable inventTable = sender as InventTable;
    if (inventTable.orig().ReqGroupId != inventTable.ReqGroupId)
    {
        NDXPOPspecificDataManagementHistory::saveChangeFromInventTable(
            inventTable.RecId
            , inventTable
            , fieldNum(InventTable, ReqGroupId)
            , [inventTable.orig().ReqGroupId]
            , [inventTable.ReqGroupId]);
    }
}
